import assert from'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';import{chapterCollections,chapterHash}from'../lib/practice-chapters.ts';const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_ENTER_OUTPUT||'outputs/enter-focus-20261101/sheets';mkdirSync(out,{recursive:true});const checks=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{for(const activity of['worksheet','worksheet-heard']){const p=await b.newPage({viewport:{width:320,height:568},hasTouch:true});try{await p.addInitScript(()=>{window.Audio=class extends EventTarget{play(){setTimeout(()=>this.dispatchEvent(new Event('ended')),30);return Promise.resolve()}pause(){}};localStorage.setItem('klink.enter.sheets','kept')});const row=chapterCollections(activity).find(r=>r.exercises.length>4),es=row.exercises;assert(row);await p.goto(base+'/'+chapterHash({chapter:'spelling',activity,collection:row.id,level:row.level,help:'practice'}));const rows=p.locator('[data-worksheet-exercise]');await rows.first().waitFor();for(let i=0;i<4;i++){const item=rows.nth(i),id=await item.getAttribute('data-worksheet-exercise'),e=es.find(e=>e.exerciseId===id);assert(e);const listen=item.locator('[data-practice-listen]');if(await listen.count()){await listen.first().click();await p.waitForTimeout(150);}for(const id of e.answer.targetTileIds)await item.locator('.cp-tile-bank > button').nth(e.tiles.findIndex(t=>t.id===id)).click();assert.equal(await item.getAttribute('data-practice-ready'),'true');if(i===0){await p.keyboard.press('Enter');assert.equal(await p.evaluate(()=>document.activeElement.closest('[data-worksheet-exercise]')?.getAttribute('data-worksheet-exercise')),es[1].exerciseId);}}await p.keyboard.press('Enter');await p.waitForTimeout(100);assert.equal(await p.locator('[data-worksheet-exercise]').first().getAttribute('data-worksheet-exercise'),es[4].exerciseId);assert.equal(await p.evaluate(()=>localStorage.getItem('klink.enter.sheets')),'kept');checks.push({engine,activity,enterFromAnswerToNextItem:true,enterFromLastAnswerToNextPage:true,storagePreserved:true});}finally{await p.close();}}}finally{await b.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors:[]},null,2)+'\n');}}
assert.equal(checks.length,4);console.log('PASS 4 worksheet mouse/Enter item and page flows.');
